INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'intimate', 'ابعت ميساج لقروب صحابك قلو: ''أنا قررت نعرس الجمعة الجاية'' ورينا التفاعل!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'intimate', 'اعمل روحك ممثل في مسلسل تونسي يعترف بحبو تحت المطر لمدة 30 ثانية!');
