INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اكتب هدفك رقم 1 للسنة هذي على منديلة ولا ورقة ووريها للشلة باش يشهدو عليك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على مشروع أحلامك في دقيقة كاملة كأنك تقدم فيه لمستثمرين باش تاخذ تمويل!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'ابعت ميساج لروحك في المستقبل (على الإيميل ولا الواتساب) واقرا بدايتو قدامنا!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل خطاب تحفيزي قصير لصحابك تشجعهم فيه باش يحققو طموحاتهم ومشاريعهم!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي 3 بلدان ناوي تزورهم في الـ 3 سنين الجايين واشرح علاش اخترتهم!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قول بصوت مسموع: ''أنا قادر ننجح ونوصل لأهدافي مهما كانت الصعوبات''!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اطلب من شخص في الطاولة يعطيك فكرة بيزنس صغيرة وتخططلها في دقيقة!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على العادة السيئة اللي ناوي تقطعها نهائياً انطلاقاً من الجمعة هذي!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك وزير الاقتصاد بعد 10 سنين وتعلن على مشاريع عملاقة لتونس!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'ورّينا أول بوست ناوي تهبطو نهار اللي تتخرج ولا تبدا خدمتك الجديدة!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي الشخص اللي باش تستدعيه أول واحد كي تحل مشروعك ولا تعرس!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على المهارة اللي قررت تتعلمها الشهر هذا وكيفاش باش تبدا فيها!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل تعهد قدام صحابك بحاجة باش تحققها قبل ما يوفى العام هذا!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'تخيل روحك بعد 20 سنة وتوجه نصيحة للجيل الصغير اللي طالع توا!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اطلب من صاحبك يكتبلك كلمة تشجيعية في النوتس متاع تليفونك لتقراها كي تفد!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على أكثر كتاب ولا دورة تدريبية فادتك وتتمنى صحابك الكل يتبعوها!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قوللنا شنوة أول سيارة تحلم تكسبها من عرق جبينك ولونها وموديلها!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك في مقابلة عمل (Entretien) في شركة عالمية وتقدم في روحك بثقة!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي 3 حاجات مادية ومعنوية تحب تملكهم قبل سن الـ 35 سنة!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على أكبر تضحية راك مستعد تعملها من أجل مستقبلك المهني والعائلي!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اطلب من المجموعة يقيّمو فكرة مشروع عندك بصراحة وبدون مجاملات!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك في مؤتمر صحفي بعد ما فزت بأكبر جائزة في اختصاصك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي العادات الصباحية اللي ناوي تلتزم باهم باش تولي شخص أكثر إنتاجية!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على أكبر درس مالي تعلمتو في حياتك وتحب تطبقو في المستقبل!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قول شنوة أول حاجة باش تشريها لوالديك نهار اللي تولي عندك فلوس بالباهي!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل تحدي رياضي بسيط توا (5 قفزات ولا تمارين تمدد) كبداية للياقة البدنية!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على البلد اللي تحب تقضي فيه شهر العسل ولا رحلة الأحلام بالتفصيل!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي الشخص الملهم ليك في حياتك وشنوة الصفة اللي تحب تكتسبها منو!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك تقدم في برنامج إذاعي عن ريادة الأعمال وتشجع الشباب التونسي!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قوللنا شنوة الاسم اللي تتمنى تسميه لصغيرك المستقبلي (ولد ولا بنت) وعلاش!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على الموقف اللي خلاك تقرر تبدل مسار حياتك وتخدم على مستقبلك بجدية!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اطلب من صحابك يقترحولك فكرة استثمار مربحة في تونس وتناقشوها باختصار!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'تخيل نهار خروجك للتقاعد كيفاش تحب تكون حياتك وصحتك وعايلتك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل تلخيص لخطة حياتك في 3 كلمات قوية (كيما: طموح، صبر، نجاح)!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على التجربة التطوعية اللي ناوي تشارك فيها لمساعدة بلادك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي المشروع الرقمي ولا التطبيق اللي تتمنى تبرمجو ولا تطلقو في تونس!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قول كلمة شكر للشخص اللي ساندك ووقف معاك في أصعب فترات قرايتك وخدمتك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك كاتب تونسي مشهور يوقع في النسخة الأولى من كتابو الجديد!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على أهم قرار استراتيجي خذيتو في حياتك وغير مجرى الأمور للأحسن!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'تعهد قدام الطاولة بزيارة صلة الرحم ولا الاتصال بأقاربك المنسيين هذا الأسبوع!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي أكبر مغامرة في الطبيعة تحب تخوضها في تونس (تسلق جبل زغوان، تخييم بالصحراء...)!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على الاستثمار اللي ندمت أنك ما عملتوش بكري وتحب تعوضو توا!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قوللنا شنوة الشعار (Slogan) اللي حاطو قدام عينيك ويمدك بالطاقة كل صباح!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اعمل روحك متحدث تحفيزي (Ted Talk) في 30 ثانية عن الإصرار وعدم الاستسلام!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'سمي الأصدقاء اللي ناوي تحافظ على صحبتهم للمستقبل حتى لو شتتكم الدنيا!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'احكي على أمنيتك لتونس في العشرية القادمة وشنوة دورك باش تساهم في بنائها!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'اطلب من الشلة يعطوك صفة وحدة لازمك تطورها باش تولي قائد ناجح في مجالك!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'قول بصوت عالي وواثق: ''مستقبلي بإذن الله مشرق وأحسن ملي نتوقع''!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'صافح صاحبك وقولو: ''وعد نتقابلو في القمة ونفرحو بنجاح بعضنا''!');
INSERT INTO party_questions (category, theme, prompt) VALUES ('ACTION', 'future', 'ابتسم ابتسامة تفاؤل عريضة وخلي الشلة ياخذولك صورة للمستقبل توا!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون أول فريق تونسي فاز بالبطولة الوطنية التونسية لكرة القدم بعد الاستقلال سنة 1956؟', 'الملعب التونسي (ST)', 'الملعب التونسي عندو تاريخ كبير، شكون فيكم لتوة يشجع البقلاوة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'قداش من مرة ترشحت تونس لنهائيات كأس العالم لكرة القدم في تاريخها؟', '6 مرات (1978, 1998, 2002, 2006, 2018, 2022)', 'أنا أحسن مشاركة وأقوى جيل في المونديال عشتوه؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون اللاعب التونسي الوحيد اللي سجل 3 أهداف (هاتريك) في مقابلة وحدة في كأس إفريقيا؟', 'فرانسيلودو دوس سانتوس (ضد زامبيا 2006)', 'شنوة رأيكم في تجنيس اللاعبين في الرياضة التونسية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الفريق التونسي اللي فاز برابطة الأبطال الإفريقية سنتي 2018 و 2019 ورا بعضهم؟', 'الترجي الرياضي التونسي (EST)', 'تتفكرو الفينال الشهير ضد الوداد في رادس؟ شنوة كان شعوركم وقتها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو السباح التونسي الأسطوري اللي فاز بزوز ميداليات ذهبية أولمبية (بكين 2008 ولندن 2012)؟', 'أسامة الملولي (القرش التونسي)', 'شكون يعتبر أسامة الملولي أعظم رياضي في تاريخ تونس؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون العداء التونسي اللي جاب أول ميدالية ذهبية أولمبية لتونس في طوكيو 1968 في سباق 5000م؟', 'محمد القمودي', 'القمودي قامة تاريخية، علاش توا عنا نقص في أبطال ألعاب القوى؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'في أنا عام فازت تونس بكأس أمم إفريقيا لكرة القدم (CAN) اللي تنظمت في بلادنا؟', 'سنة 2004', 'أنا أحسن لقطة تفكروها من فينال 2004 ضد المغرب؟ قداش كانت الفرحة في الشارع؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هي البطلة التونسية العالمية في التنس الملقبة بـ ''وزيرة السعادة''؟', 'أنس جابر (Ons Jabeur)', 'شنوة أحسن ماتش تفرجتو فيه لأنس جابر وحرق أعصابكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون صاحب أول هدف لتونس في تاريخ كأس العالم ضد المكسيك 1978 في الأرجنتين؟', 'علي الكعبي', 'ملحمة الأرجنتين 78 هل هي المعجزة الكروية التونسية الأولى؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الفريق التونسي الملقب بـ ''قلعة الأجداد'' ولا ''CSS''؟', 'النادي الرياضي الصفاقسي', 'النادي الصفاقسي ومدرسة الكورة الأنيقة، شكون يحب اللعب الصفاقسي الكلاسيكي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو هداف المنتخب التونسي التاريخي في كل المسابقات الرسمية؟', 'عصام جمعة (Issam Jemâa بـ 36 هدف)', 'برشا ناس كانت تنبر على عصام جمعة وتوا يقولو ليتنا نلقاو مهاجم كيفو! شنوة رأيكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو النادي التونسي اللي فاز بالرباعية التاريخية (بطولة، كأس، إفريقيا، عربية) في موسم 1991/1992؟', 'النادي الإفريقي (CA)', 'جيل التسعينات في النادي الإفريقي، شكون يتفكر عادل السليمي والرويسي ولطفي الرويسي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون البطل التونسي اللي فاز بذهبية التايكوندو في أولمبياد باريس 2024 وسبقلو فضية طوكيو؟', 'فراس القطوسي (وخليل الجندوبي)', 'الرياضات الفردية ديما تشرف تونس أكثر من الجماعية، علاش في رأيكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون أول فريق تونسي فاز بكأس الكاف (CAF Cup) في نسختها القديمة سنة 1995؟', 'النجم الرياضي الساحلي (ESS)', 'النجم الساحلي وتاريخو الإفريقي العريض، شكون يتفكر فينالات سوسة الحماسية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الحارس التونسي التاريخي الملقب بـ ''عتوقة'' وأسطورة حراسة المرمى؟', 'الصادق ساسي (عتوقة)', 'هل عتوقة وشكري الواعر هما أحسن زوز حراس في تاريخ تونس ولا فما غيرهم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون المدرب التونسي اللي قاد المنتخب للقب كأس إفريقيا التاريخي عام 2004؟', 'روجيه لومير (Roger Lemerre)', 'المدرب الأجنبي ولا التونسي: شكون أنجح مع المنتخب الوطني في رأيكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'قداش من فريق يلعب عادة في الرابطة المحترفة الأولى التونسية لكرة القدم (النسخة الكلاسيكية)؟', '14 إلى 16 فريق', 'شنوة رأيكم في نظام البطولة التونسية توا وبطولة البلاي أوف؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون البطلة التونسية اللي فازت بذهبية سباق 3000م موانع في أولمبياد لندن 2012؟', 'حبيبة الغريبي', 'حبيبة الغريبي وفرحة التوانسة بالذهب، شنوة يمثللكم الإنجاز الرياضي النسائي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الملعب الأكبر في تونس اللي يتسع لحوالي 60 ألف متفرج؟', 'الملعب الأولمبي برادس (حمادي العقربي)', 'شنوة أحسن ماتش حضرتو في رادس وعشت فيه أجواء خيالية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون اللاعب التونسي الملقب بـ ''المايسترو'' و ''ساحر الأجيال'' وأسطورة النادي الصفاقسي؟', 'حمادي العقربي رحمه الله', 'حمادي العقربي وأخلاقه العالية، شكون يعتبرو أسطورة كرة القدم التونسية الأولى؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو المخرج التونسي لمسلسل ''شوفلي حل'' الشهير وسلسلة ''سيتكوم'' التونسية الأنجح؟', 'صلاح الدين الصيد رحمه الله', 'مسلسل شوفلي حل لتوة التوانسة يعاودو يتفرجو فيه وما يفدوش! علاش في رأيكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الممثل اللي مثل دور ''السبوعي'' في مسلسل شوفلي حل ودخل قلوب كل التوانسة؟', 'سفيان الشعري رحمه الله', 'أنا أحسن حلقة ولا قفشة تتفكروها للسبوعي والزين وفوفا؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم العيادة والمهنة متاع ''الدكتور سليمان الأبيض'' في شوفلي حل؟', 'طبيب نفساني (Psychiatre)', 'لو كان تمشي لطبيب نفساني، تستعرف بيها قدام صحابك ولا تحشم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الممثل الكوميدي اللي مثل دور ''فوشيكة'' صاحب السبوعي في شوفلي حل؟', 'فيصل بالزين', 'ثنائية السبوعي وفوشيكة، شكون عندو صاحب في الطاولة كيما فوشيكة وديما يدخلو في حيط؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون المخرج التونسي لمسلسل ''الخطاب على الباب'' و ''الدوار'' و ''صيد الريم''؟', 'صلاح الدين الصيد (سيناريو علي اللواتي)', 'مسلسل الخطاب على الباب في رمضان زمان: شكون يتفكر لمة العايلة في التسعينات؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الشخصية الشهيرة اللي مثلها منصف السويسي في مسلسل الدوار وعاشت في ذاكرة التوانسة؟', 'الرديسي (أو ساسي / صالحة / حليمة)', 'مسلسل الدوار كأول دراما ريفية تونسية قوية، شكون تفرج فيه وتأثر باها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون المخرج التونسي العالمي صاحب فيلم ''عصفور السطح'' (حلفاوين) سنة 1990؟', 'فريد بوغدير (Férid Boughedir)', 'فيلم حلفاوين والسينما التونسية في التسعينات: شنوة يعنيلكم الفيلم هذا؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هي الممثلة التونسية اللي فازت بجائزة أحسن ممثلة في مهرجان كان عن فيلم ''بنات ألفة''؟', 'هند صبري (أو الفيلم لكوثر بن هنية)', 'شنوة رأيكم في نجاح السينما التونسية في المهرجانات العالمية كيما الأوسكار وكان؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم السلسلة الهزلية الرمضانية الشهيرة بطولة الأمين النهدي ونور الدين بن عياد في التسعينات؟', 'سي الزاهي / قهوة جلول / سلسلة ''فندق الجديد''', 'الأمين النهدي في قمة مسرحياته ومسلسلاته، شكون تفرج في ''المكي وزكية''؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الممثل التونسي صاحب مسرحية ''المكي وزكية'' و ''فيها ما يتغنى''؟', 'الأمين النهدي', 'مسرحية المكي وزكية دارت العالم العربي كامل، شنوة أحسن مسرحية وان مان شو شوفتوها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم المسلسل التونسي الرمضاني اللي حكى على عالم المخدرات والشباب بطولة فتحي الهداوي؟', 'صيد الريم (أو مسلسل مكتوب)', 'مسلسل مكتوب وقت خرج في 2008 قلب الدنيا وبدل طريقة تصوير المسلسلات في تونس! موافقين؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو الممثل التونسي القدير الملقب بغول الشاشة التونسية صاحب دور ''محمود'' في مكتوب؟', 'فتحي الهداوي', 'فتحي الهداوي وصوته الرخيم، شكون يعتبرو أقوى ممثل درامي في تونس؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الممثلة التونسية صاحبة دور ''فايقة أم السبوعي'' في شوفلي حل؟', 'خديجة السويسي (دوجة)', 'أمهات المسلسلات التونسية: دوجة السويسي، منى نور الدين، دليلة مفتاحي... شكون أحسن ممثلة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الشخصية اللي مثلها كمال التواتي في ''نسيبتي العزيزة'' بجنب الفاهم والخميسة؟', 'حسونة الوحيشي', 'نسيبتي العزيزة والفاهم (خالد بوزيد)، شنوة أكثر لقطة ضحكتكم في المسلسل؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون المخرجة التونسية اللي ترشحت للأوسكار بفيلم ''الرجل الذي باع ظهره'' و ''بنات ألفة''؟', 'كوثر بن هنية (Kaouther Ben Hania)', 'المخرجة كوثر بن هنية وتشريف تونس في هوليوود، فخورين بالسينما التونسية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم برنامج الكاميرا الخفية الشهير للمخرج رؤوف كوكة اللي كان يتعدى في شق الفطر؟', 'الكاميرا الخفية (رؤوف كوكة)', 'الكاميرا الخفية زمان متاع رؤوف كوكة ولا الكاميرات الخفية الجديدة بالبيجامات والمقالب؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو الممثل صاحب شخصية ''بوشناق'' ولا ''الطيب'' في مسلسل حسابات وعقابات؟', 'فتحي الهداوي / هشام رستم / كمال التواتي', 'حسابات وعقابات وغناية الجنيريك الشهيرة لصابر الرباعي، شكون يتفكرها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الشخصية اللي مثلها ظافر العابدين في مسلسل مكتوب وكانت سبب شهرته الكبيرة في تونس؟', 'محمد علي (دالي)', 'ظافر العابدين وانتقاله للدراما المصرية والعالمية، شكون يتبع في مسلسلاتو؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الممثلة القديرة صاحبة دور ''فضيلة'' في مسلسل الخطاب على الباب؟', 'منى نور الدين', 'منى نور الدين سيدة الشاشة التونسية، شكون يعطيها وسام الإبداع الأول في تونس؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الفيلم التونسي الكوميدي الشهير للمخرج إبراهيم اللطيف بطولة لطفي العبدلي في دور ساحر؟', 'فيزا (Visa) / أو ''هز موراك وطير'' / ''ماشين لجهنم''', 'لطفي العبدلي في الوان مان شو والسينما، شنوة رأيكم في أسلوبو الجريء؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو الفنان التونسي الملقب بـ ''صاحب الحنجرة الذهبية'' وصاحب غناية ''سيدي منصور'' و ''أتحدى العالم''؟', 'صابر الرباعي (أمير الطرب العربي)', 'أنا أحسن غناية تعجبكم لصابر الرباعي وتسمعوها ديما؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هي الفنانة التونسية القديرة صاحبة رائعة ''ريتك ما نعرف وين'' و ''جاري يا حمودة''؟', 'عليا التونسية (أو فتون / صليحة)', 'الفن التونسي القديم وجمال الصوت، شكون فيكم يسمع المالوف والطرب التونسي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنان التونسي الشعبي الملقب بـ ''ملك المزود'' وصاحب غناية ''يا ليموني'' و ''حب يختال''؟', 'صالح الفرزيط (أو الهادي حبوبة)', 'الهادي حبوبة ونقلة المزود للمسرح والقرطاج، شكون يحب جو الجو التونسي والمزود في السهرات؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون صاحب عرض ''الحضرة'' الصوفي التونسي العالمي اللي انطلق في التسعينات؟', 'الفاضل الجزيري وسمير العقربي', 'عرض الحضرة وجو البنادير والمدائح، شكون حضرلو في مهرجان قرطاج قبل؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنانة التونسية صاحبة الصوت الأوبرالي وغنايات ''أهواك'' و ''كلماتي'' ولقب سفيرة الأغنية التونسية؟', 'يسرى المحنوش (أو لطيفة العرفاوي / ذكرى محمد)', 'ذكرى محمد رحمها الله وصوتها الأسطوري، هل هي أعظم صوت عربي خرج من تونس؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الرابر التونسي صاحب غنايات ''حومة تحب تعيش'' و ''البلطية'' ورائد الراب التونسي؟', 'بلطي (Balti)', 'بلطي ونجاح غناية ''يا ليلي'' اللي فاقت المليار مشاهدة، شكون يعتبر بلطي فخر تونس في الراب؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو المهرجان الدولي العريق في تونس اللي يقام في المسرح الأثري الروماني كل صيف؟', 'مهرجان قرطاج الدولي (Festival International de Carthage)', 'شنوة أحسن حفلة سهرتو باها في مسرح قرطاج الروماني؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الشاعر التونسي الكبير صاحب البيت الشهير: ''إذا الشعب يوماً أراد الحياة * فلا بد أن يستجيب القدر''؟', 'أبو القاسم الشابي', 'أبو القاسم الشابي فخر تونس وتوزر، شكون حافظ أبيات أخرى من شعرو؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنان التونسي الشعبي صاحب غناية ''يا خالي يا مدلل'' و ''الزين هذا كلو منين''؟', 'سمير لوصيف', 'سمير لوصيف وإحساس المزود الحزين، شكون يروق على غنايات لوصيف في الكرهبة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الآلة الموسيقية الوترية التقليدية التونسية المشتقة من العود وتستعمل في المالوف؟', 'العود التونسي (العود العربي ذو 4 أوتار)', 'الموسيقى التونسية والمالوف التونسي، شكون يحب قعدة التخت العربي في سيدي بوسعيد؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنان التونسي صاحب غناية ''عشاقة'' و ''يا بنيّة'' وأحد نجوم الأغنية الملتزمة والشبابية؟', 'الهادي قلة / ياسر الجرادي / سمير العقربي (النوبة)', 'غناية ''شبيك نسيتني يا ولدي'' و ''نرجعلك ديما'': شكون يحب الغناء الملتزم الهادي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الرابر التونسي الملقب بـ ''A.L.A'' صاحب ألبومات ''Chronicles'' والراب القوي؟', 'A.L.A (علاء)', 'الراب التونسي والجيل الجديد (A.L.A, Samara, Kaso, JenJoon, Nordo): شكون رقم 1 عندك؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنان التونسي اللي لمع في التمثيل والغناء بأغاني ''يا دنيا'' و ''عربوش'' و ''زهري وين''؟', 'نوردو (Nordo)', 'نوردو وتحولو من الراب للغناء الشعبي العاطفي والتمثيل في الفلوجة، شنوة رأيكم في تجربتو؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو المهرجان السينمائي الأقدم في إفريقيا والعالم العربي اللي تأسس في تونس عام 1966؟', 'أيام قرطاج السينمائية (JCC)', 'أجواء الـ JCC في شارع الحبيب بورقيبة ودور السينما، شكون يتبع الأفلام في الشتاء؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم المهرجان المسرحي السنوي العريق اللي يتنظم في العاصمة تونس؟', 'أيام قرطاج المسرحية (JTC)', 'المسرح التونسي وقوته وجرأته، شكون مشى للمسرح الوطني في قاعة الفن الرابع؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنانة التونسية اللي غنت ''أنا بعشق البحر'' و ''أكتر من اللي أنا بحلم بيه'' ولها شهرة عالمية؟', 'نجاة الصغيرة / لطيفة التونسية / غالية بن علي', 'غالية بن علي وطريقتها الفريدة في الغناء الصوفي والغجري، شكون يسمعها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون صاحب الأغنية التونسية التراثية الشهيرة ''بابا بحري يا سيدي علي الحطاب''؟', 'التراث التونسي الصوفي / الهادي حبوبة في النوبة', 'خرجة سيدي بن عروس وسيدي محرز: شنوة رأيكم في الحفلات الشعبية التونسية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الفرقة التونسية المعاصرة صاحبة أغاني الروك التونسي الممزوج بالمالوف؟', 'ميراث (Myrath)', 'فرقة ميراث العالمية ونجاحها في أوروبا بالميتال الشرقي التونسي، شكون يعرفهم فيكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون الفنان الشعبي التونسي صاحب غناية ''حرمت ركوب الخيل'' التراثية؟', 'إسماعيل الحطاب', 'إسماعيل الحطاب وبدو الجنوب والوسط التونسي، الأغنية البدوية التونسية وأصالتها!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الآلة الإيقاعية الجلدية التونسية اللي يعزفو باها في المزود والسطمبالي؟', 'الدربوكة، البندير، والطبلة التونسية', 'شكون فيكم يعرف يضرب على الدربوكة في القعدة ويعمللنا جو توا؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هي الأميرة الفينيقية الأسطورية اللي أسست مدينة قرطاج العظيمة سنة 814 قبل الميلاد؟', 'الملكة عليسة (Didon / Elissa)', 'تاريخ قرطاج وعليسة، كان جيت في وقتها شنوة البلاصة اللي تختار تبني فيها مدينتك؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو القائد العسكري القرطاجي الأسطوري اللي غزا روما وعبر جبال الألب بالأفيال؟', 'حنبعل برقا (Hannibal Barca)', 'حنبعل يعتبر من أعظم عباقرة الحرب في التاريخ البشري، فخورين بيه كرمز تونسي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الجامع التاريخي في تونس اللي يعتبر رابع أقدس مكان في الإسلام وأقدم منارة في المغرب العربي؟', 'جامع عقبة بن نافع في القيروان (تأسس 670م)', 'جامع عقبة والقيروان ومدينة الأغالبة والمقروض، شكون زار القيروان في المولد؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو المعلم الروماني الضخم في تونس اللي يعتبر ثاني أكبر مسرح دائري في العالم بعد كولوسيوم روما؟', 'قصر الجم (مسرح الجم الأثري)', 'قصر الجم والسينما العالمية وتصوير الأفلام، شكون زار الجم وطلع لأعلى مدارجه؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون هو المؤرخ وعالم الاجتماع التونسي العبقري مؤسس علم الاجتماع ومؤلف ''المقدمة''؟', 'ابن خلدون (ولد بتونس 1332م)', 'تمثال ابن خلدون في شارع بورقيبة: ابن خلدون ونظرياته لتوة تدرس في أكبر جامعات العالم!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو الموقع الأثري التونسي في الشمال الغربي اللي فيه أحسن كابيتول ومسرح روماني محفوظ في العالم؟', 'دقة (Dougga / دقة الأثرية في باجة)', 'دقة ومناظر طبرقة وعين دراهم، شكون مغروم بالروندوني في تونس؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الجزيرة التونسية الملقبة بـ ''جزيرة الأحلام'' وجزيرة المساجد والأشجار العريقة؟', 'جزيرة جربة (Djerba)', 'جربة والغريبة وحومة السوق والفخار، شكون مشى لجربة وعاش السحر متاعها؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية التاريخية الملقبة بـ ''عاصمة الأغالبة'' ومدينة الصحابة والمقروض والزربية؟', 'القيروان', 'مقروض القيروان بالعسل والتمر واللوز، شكون يجيب معاه كعبة مقروض سخونة ديما؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الشط المالح والبحيرة الجافة الشاسعة في الجنوب التونسي اللي صورت فيها سلسلة Star Wars؟', 'شط الجريد (Chott El Jerid بين توزر وقبلي)', 'توزر ونفطة وشط الجريد وسياحة الصحراء، شكون يحب الجنوب التونسي في الشتاء؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي القرية التونسية الساحلية الساحرة بلونها الأبيض والأزرق ومقهى الشعانين العريق؟', 'سيدي بوسعيد (Sidi Bou Saïd)', 'قهوة العالية ولا القهوة العالية والبمبالوني في سيدي بوسعيد، شكون يفضل قعدة العشوية غادي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شكون أول رئيس للجمهورية التونسية بعد إلغاء الملكية سنة 1957؟', 'الحبيب بورقيبة', 'الحبيب بورقيبة والتعليم ومجلة الأحوال الشخصية، شنوة رأيكم في التاريخ السياسي التونسي؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'في أنا تاريخ تحتفل تونس بعيد الاستقلال الوطني كل عام؟', '20 مارس (1956)', '20 مارس وعيد الاستقلال، شنوة يعني الاستقلال الحقيقي للشباب التونسي توا؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية الملقبة بـ ''لؤلؤة الساحل'' ومركز السياحة والتاريخ؟', 'سوسة (Sousse)', 'سوسة والقنطاوي والرباط، شكون يحب جو الساحل التونسي في الصيف؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي أعلى قمة جبلية في الجمهورية التونسية بارتفاع 1544 متر؟', 'جبل الشعانبي (في ولاية القصرين)', 'طبيعة تونس وجبالها من عين دراهم للشعانبي لمطماطة، بلادنا قداش متنوعة ومزيانة!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم المدينة التونسية المشهورة بمنازلها المحفورة تحت الأرض (المنازل الحفرية) وغار الديار؟', 'مطماطة (Matmata في قابس)', 'مطماطة وتصوير فيلم حرب النجوم، شكون بات في دار حفرية تحت الأرض قبل؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية المعروفة بأقصى نقطة في شمال القارة الإفريقية؟', 'بنزرت (رأس أنجلة / Cap Angela)', 'بنزرت والكانال والكورنيش ولبلابي بنزرت الحار، شكون يعشق بنزرت؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية المشهورة بصناعة الفخار الملون منذ آلاف السنين؟', 'نابل (Nabeul) وجربة (قلال)', 'فخار نابل وهريسة نابل والزهر والبرتقال، شكون يحب ريحة الزهر في الربيع بنابل؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الباي التونسي اللي وقع على مرسوم إلغاء العبودية في تونس سنة 1846 قبل برشا دول أوروبية؟', 'أحمد باي الأول', 'تونس أول دولة عربية وإسلامية ألغت الرق سنة 1846، فخر تاريخي كبير!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهو البحر ولا البحيرة الساحلية اللي في شمال تونس والمحمية الطبيعية للطيور المهاجرة وسجلت باليونسكو؟', 'محمية بحيرة إشكيل (Ichkeul في بنزرت)', 'محمية إشكيل وجاموس الماء، شكون زارها وشاف الطيور النادرة والفيجيتاليسيون؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي الولاية التونسية المشهورة بـ ''دقلة النور'' التونسية المصنفة كأحسن تمور في العالم؟', 'توزر وقبلي (منطقة الجريد ونفزاوة)', 'دقلة النور التونسية الشفافة بالعسل متاعها، شنوة أحسن دقلة كليتوها في حياتكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة الأكلة التونسية الوطنية اللي مسجلة في التراث العالمي لليونسكو؟', 'الكسكسي التونسي (Couscous)', 'كسكسي بالعلوش ولا بالحوت ولا بالقديد والقرنيط: شنوة الكسكسي المفضل عندكم؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة المكون السري التونسي الحار المصنوع من الفلفل والثوم والكروية والتابل ومسجل باليونسكو؟', 'الهريسة التونسية (Harissa)', 'الهريسة العربي مع زويتة زيتونة وخبز طابونة سخون، شكون ما ينجمش يعيش بلاش هريسة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الأكلة التونسية الشعبية الصباحية والشتوية المصنوعة من الحمص والكمون وزيت الزيتونة والخبز اليابس؟', 'اللبلابي (Lablabi)', 'لبلابي بالعظمة والكفكير والتن والهرقمة: شكون أحسن واحد ياكل لبلابي حار في الشلة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة الأكلة المقلية المقرمشة التونسية اللي ما تغيبش على حتى طاولة في رمضان بالعظمة والتن؟', 'البريك التونسي (Brik à l''oeuf)', 'البريكة التونسية كيفاش تحب العظمة متاعها: رايبة تسيل ولا طايبة برشا؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم السلاطة التونسية المشوية على الفحم المصنوعة من الفلفل والطماطم والثوم؟', 'السلاطة المشوية (Salade Méchouia)', 'سلاطة مشوية مدقوقة بالمهراس ولا مرحية بالماكينة؟ أني أبن وأصلية؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم السندويتش التونسي الشهير المليء بالتن والسلاطة المشوية والبطاطا والزيتون في خبز مدور؟', 'الكفتاجي التونسي / الشاباتي (Chapati) / الفريكاسي (Fricassé)', 'الفريكاسي التونسي الصغير المقلي، شكون ينجم ياكل 5 كعبات في قعدة وحدة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية المشهورة بسندويتش ''الشاباتي'' العملاق المحشو بالأومليت والفرماج؟', 'شاباتي المهدية (وصفاقس وتونس)', 'شاباتي المهدية السخون بالجبن والاسكالوب، شكون يفضلو على البيتزا والبرغر؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم المشروب الغازي التونسي التاريخي المصنوع من التفاح اللي يعشقوه التوانسة من الخمسينات؟', 'أبليكا / بوقا سيدر (Boga Cidre)', 'بوقا سيدر ولا بوقا بيضاء بالليمون مع كسكروت كفتاجي، فما أحسن من هكا فطور؟');
