INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الخبز التونسي التقليدي المطهو في فرن الطين على الحطب والجمر؟', 'خبز الطابونة (Tabouna)', 'خبز طابونة سخون خارج توا مع زيت زيتونة وزعتر وهريسة عربي، نعمة ربي الكبيرة!');
