INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة المشروب الساخن التونسي التقليدي اللي يقدموه في القهاوي وفوقو لوز ولا بندق؟', 'التاي بالبندق (Thé aux pignons) والتاي باللوز', 'تاي أخضر منعنع ولا تاي أحمر مخمّخ طايب على الجمر، شنوة جوك في القهوة؟');
