INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة المشروب الساخن التونسي التقليدي اللي يقدموه في القهاوي وفوقو لوز ولا بندق؟', 'التاي بالبندق (Thé aux pignons) والتاي باللوز', 'شكون فيكم كان حاضر ولا يتفكر اللحظة هذي؟ احكيولنا شعوركم!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الأكلة التونسية الخفيفة المقلية المحشوة بالتن والهريسة والعظام تباع في كل حومة؟', 'الفريكاسي (Fricassé)', 'شنوة رأي الطاولة الكل في هالموضوع؟ هل تتفقوا مع هالإجابة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'أناهي المدينة التونسية المعروفة بألذ أنواع السمك والقرنيط والمهرجان السنوي للقرنيط؟', 'قرقنة (Kerkennah) والشابة وجرجيس', 'شكون فيكم كان حاضر ولا يتفكر اللحظة هذي؟ احكيولنا شعوركم!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الأكلة التونسية المكونة من الخضار المقلية (قرع، بطاطا، طماطم، فلفل) ومقطعة بالسكاكن مع كبدة وعظام؟', 'الكفتاجي التونسي (Kaftaji)', 'شنوة رأي الطاولة الكل في هالموضوع؟ هل تتفقوا مع هالإجابة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الشربة التونسية الكلاسيكية اللي تبدا باها كل طاولة تونسية في رمضان بالقرنيط ولا بالعلوش؟', 'شربة شعير (Chorba Frik / لسان عصفور)', 'شكون فيكم كان حاضر ولا يتفكر اللحظة هذي؟ احكيولنا شعوركم!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الحلوى التونسية الفاخرة المصنوعة من اللوز والسكر وتتلون على شكل غلال صغيرة؟', 'كعك الورقة والملبس والفواكه المصنوعة باللوز (Pâte d''amande)', 'شنوة رأي الطاولة الكل في هالموضوع؟ هل تتفقوا مع هالإجابة؟');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم المشروب الطبيعي التونسي المنعش المصنوع من اللوز المرحي والسكر في الصيف والأعراس؟', 'الروزاطة التونسية (Horchata / Sirop d''Orgeat)', 'شكون فيكم كان حاضر ولا يتفكر اللحظة هذي؟ احكيولنا شعوركم!');
INSERT INTO party_questions (category, theme, prompt, answer, discussion) VALUES ('QUIZ', 'general', 'شنوة اسم الفطور التونسي الصباحي التقليدي المصنوع من القمح المحمص المرحي مع السكر وزيت الزيتونة؟', 'الدرع (Draa) والبسيسة التونسية (Bsissa)', 'شنوة رأي الطاولة الكل في هالموضوع؟ هل تتفقوا مع هالإجابة؟');
